            ["الملف أو المجلد مو موجود."] = "الملف أو المجلد غير موجود.",
            ["الملف الأصلي ينحفظ مخفي 30 يوم، فلو غيّرت رايك ترجعه."] = "يُحفظ الملف الأصلي مخفيًا 30 يومًا، فإن غيّرت رأيك تستعيده.",
