            ["شغّال الحين: {0}"] = "يعمل الآن: {0}",
            ["شغّال: يسجّل الشاشة الرئيسية بالخلفية عشان تقدر تحفظ آخر دقيقة. ياخذ شوي من الجهاز"] = "يعمل: يسجّل الشاشة الرئيسية في الخلفية لتتمكن من حفظ آخر دقيقة. يستهلك قليلًا من موارد الجهاز",
            ["شغّل اللي تبيه يبان على التاسك بار، والباقي يكون تحت السهم."] = "شغّل ما تريد ظهوره على شريط المهام، والباقي يكون تحت السهم.",
            ["شغّله الحين بدون لعبة"] = "شغّله الآن دون لعبة",
            ["شغّله بعد ما تنسخ، أو حطه على الضغط على خلف الجوال (الإعدادات ← تسهيلات الاستخدام ← اللمس ← الضغط على الخلف)."] = "شغّله بعد النسخ، أو اربطه بالضغط على ظهر الهاتف (الإعدادات ← تسهيلات الاستخدام ← اللمس ← الضغط على الخلف).",
            ["شغّله مرة وخلاص: أول ما تفتح لعبة يوقف Windows Update و SysMain وخدمات الخلفية اللي تختارها، ويسكّر برامج مثل OneDrive و Teams لو اخترتها، ويرفع أولوية اللعبة. أول ما تطلع منها يرجّع كل شي لحاله. يعرف ألعاب Steam و Epic و Xbox وغيرها لحاله، وتقدر تضيف لعبتك. أول مرة ويندوز يطلب صلاحية المسؤول مرة وحدة بس."] = "شغّله مرة واحدة وانتهى الأمر: بمجرد فتح لعبة يوقف Windows Update وSysMain وخدمات الخلفية التي تختارها، ويغلق برامج مثل OneDrive وTeams إن اخترتها، ويرفع أولوية اللعبة. وبمجرد الخروج منها يعيد كل شيء كما كان. يتعرّف على ألعاب Steam وEpic وXbox وغيرها تلقائيًا، ويمكنك إضافة لعبتك. في المرة الأولى يطلب ويندوز صلاحية المسؤول مرة واحدة فقط.",
            ["شغّله من Wibn ← تصوير الشاشة عشان يحفظ آخر دقيقة"] = "شغّله من Wibn ← تصوير الشاشة ليحفظ آخر دقيقة",
