            ["مثل سطح المكتب أو أي مجلد مليان ملفات. أو كليك يمين على المجلد ← ترتيب الملفات حسب النوع (في ويندوز 11 تحت: عرض المزيد من الخيارات)"] = "مثل سطح المكتب أو أي مجلد مليء بالملفات. أو انقر بالزر الأيمن على المجلد ← ترتيب الملفات حسب النوع (في ويندوز 11 تحت: عرض المزيد من الخيارات)",
            ["مجلد Temp حقك. الملفات اللي عمرها أقل من يوم تنترك عشان ما يخرب تثبيت شغال."] = "مجلد Temp الخاص بك. تُترك الملفات التي عمرها أقل من يوم حتى لا يتضرر تثبيت جارٍ.",
            ["مجلد التحميلات يبقى مرتب للأبد، وتلقى الملف بسرعة."] = "يبقى مجلد التنزيلات مرتبًا دائمًا، وتجد الملف بسرعة.",
            ["محدد {0} ملف  ({1})"] = "حُدّد {0} ملف  ({1})",
            ["مساحة كاملة للعبة أو المقطع، والتاريخ كامل بنظرة."] = "مساحة كاملة للعبة أو المقطع، والتاريخ كاملًا بنظرة.",
            ["مسجّل. يستخدم تسجيل دخولك بس لما الموقع يطلبه (مثل كل صور بوست انستقرام، وريديت). لو وقف يشتغل اضغط \"سجّل دخول\" مرة ثانية."] = "مسجّل الدخول. يستخدم تسجيل دخولك فقط عندما يطلبه الموقع (مثل جميع صور منشور إنستغرام، وريديت). إذا توقف عن العمل فاضغط «سجّل الدخول» مرة أخرى.",
            ["مشكلة في النت. جرّب مرة ثانية."] = "مشكلة في الاتصال بالإنترنت. حاول مرة أخرى.",
            ["مطلوب للمقاطع والصوت وWEBP وAVIF (مجاني، تقريبًا 140 ميقا). الصور الثانية ما تحتاجه"] = "مطلوب للمقاطع والصوت وWEBP وAVIF (مجاني، نحو 140 ميغابايت). لا تحتاجه الصور الأخرى",
            ["مكان الساعة في التاسك بار"] = "مكان الساعة في شريط المهام",
            ["ملف 7Z يحتاج أداة 7-Zip الصغيرة وما قدرت أحمّلها. تأكد من النت."] = "يحتاج ملف 7Z إلى أداة 7-Zip الصغيرة، وتعذّر تنزيلها. تأكد من الاتصال بالإنترنت.",
            ["ملف مقفول (Wibn)"] = "ملف مقفل (Wibn)",
            ["ملف نظام أو ويندوز، ما ينحذف عشان ما يخرب الجهاز."] = "ملف نظام أو ملف ويندوز، لا يُحذف حتى لا يتضرر الجهاز.",
            ["ملفات المعاينة اللي يسويها After Effects و Premiere. ترجع تنبني لما تفتح المشروع."] = "ملفات المعاينة التي ينشئها After Effects وPremiere. يُعاد بناؤها عند فتح المشروع.",
            ["ملفات تحديثات ويندوز المحملة"] = "ملفات تحديثات ويندوز المنزّلة",
            ["ملفات مؤقتة وكاش يرجع ويندوز والبرامج يسوونها من جديد، فحذفها آمن. اقفل المتصفحات قبل عشان ينحذف كاشها."] = "ملفات مؤقتة وذاكرة تخزين مؤقت تعيد ويندوز والبرامج إنشاءها، فحذفها آمن. أغلق المتصفحات قبل ذلك ليُحذف تخزينها المؤقت.",
            ["ملفات مقفولة (*.wplock)|*.wplock"] = "ملفات مقفلة (*.wplock)|*.wplock",
            ["ملفات ويندوز والبرامج يسوونها مؤقتًا وينسونها."] = "ملفات تنشئها ويندوز والبرامج مؤقتًا ثم تنساها.",
            ["ملفاتك الخاصة تبقى خاصة، حتى لو أحد استخدم جهازك أو أخذ الملف."] = "تبقى ملفاتك الخاصة خاصة، حتى لو استخدم أحد جهازك أو أخذ الملف.",
            ["من أي مكان اضغط Ctrl+H والصق رابط من يوتيوب أو انستا أو تويتر أو تيك توك أو سبوتيفاي، وتختار الجودة أو صوت بس."] = "من أي مكان اضغط Ctrl+H والصق رابطًا من يوتيوب أو إنستغرام أو تويتر أو تيك توك أو سبوتيفاي، واختر الجودة أو الصوت فقط.",
            ["من أي مكان، اضغط الاختصار ويطلع شريط بنص الشاشة. الصق رابط المقطع والشريط يختفي على طول، "] = "من أي مكان، اضغط الاختصار ليظهر شريط في منتصف الشاشة. الصق رابط المقطع فيختفي الشريط فورًا، ",
            ["من الكمبيوتر"] = "من الحاسوب",
            ["من النظام: إنهاؤه ممكن يخرّب شي في ويندوز أو يطفي جزء منه"] = "من النظام: قد يُفسد إنهاؤه شيئًا في ويندوز أو يوقف جزءًا منه",
            ["من جهاز لجهاز مباشرة"] = "من جهاز إلى جهاز مباشرة",
            ["من صفحة التاسك بار شغّل \"أيقونات بيضاء\" وتصير كل أيقونات تاسك بار Wibn (البرامج واللي جنب الساعة) بالأبيض وشفافة شوي، والأجزاء الفاتحة فيها تبقى أوضح. طفّه وترجع ألوانها. وأي برنامج عنده رسائل ما قريتها (ديسكورد، المتصفح، واتساب…) يطلع على أيقونته نقطة حمرا، ولو فيه عدد يطلع الرقم. Wibn ياخذها من اسم نافذة البرنامج مثل \"(3) Discord\". ولما تضغط على برنامج، نافذته تطلع فوق كل النوافذ."] = "من صفحة شريط المهام شغّل «أيقونات بيضاء» لتصبح جميع أيقونات شريط مهام Wibn (البرامج والمجاورة للساعة) بيضاء وشبه شفافة، وتبقى أجزاؤها الفاتحة أوضح. أوقفه لتعود ألوانها. وأي برنامج لديه رسائل غير مقروءة (ديسكورد، والمتصفح، وواتساب…) تظهر على أيقونته نقطة حمراء، ويظهر العدد إن وُجد. يأخذها Wibn من اسم نافذة البرنامج مثل «(3) Discord». وعند الضغط على برنامج تظهر نافذته فوق جميع النوافذ.",
            ["من صفحة الويدجتات ← لون الكتابة اختر \"لون أختاره\" وحدد اللون من المنتقي، وتصير كل كتابة الويدجتات بهاللون: الكتابة البيضاء والرمادية مع بعض (الرمادية تبقى أخف شوي بنفس اللون). ترجّعها \"تلقائي\" وتصير الكتابة غامقة أو فاتحة لحالها حسب اللي وراها. الويدجتات اللي لها لون كتابة خاص فيها (مثل ويدجت الكتابة) تبقى على لونها."] = "من صفحة الودجات ← لون الكتابة اختر «لون أختاره» وحدد اللون من المنتقي، فتصبح كل كتابة الودجات بهذا اللون: الكتابة البيضاء والرمادية معًا (وتبقى الرمادية أخف قليلًا باللون نفسه). أعِدها إلى «تلقائي» لتصبح الكتابة داكنة أو فاتحة تلقائيًا حسب ما خلفها. أما الودجات التي لها لون كتابة خاص (مثل ودجة الكتابة) فتبقى على لونها.",
            ["مو متصل"] = "غير متصل",
            ["مواعيدك قدامك على سطح المكتب، والجهاز يذكّرك فيها."] = "مواعيدك أمامك على سطح المكتب، والجهاز يذكّرك بها.",
            ["موجات تتحرك مع الصوت اللي يطلع من السماعة أو لما تتكلم في المايك. كليك يمين عليه عشان تختار الجهاز والشكل"] = "موجات تتحرك مع الصوت الصادر من مكبر الصوت أو عند تحدثك في الميكروفون. انقر عليها بالزر الأيمن لاختيار الجهاز والشكل",
            ["نافذة سطح المكتب ونافذة التقويم تفتح بحركة تكبر شوي وتبان. تختار كم تاخذ، وتتسكّر بأسرع من كذا شوي. 0 = تطلع على طول بدون حركة."] = "تُفتح نافذة سطح المكتب ونافذة التقويم بحركة تكبر قليلًا ثم تظهر. تختار المدة التي تستغرقها، وتُغلق أسرع من ذلك قليلًا. 0 = تظهر فورًا دون حركة.",
            ["نسخة جديدة: {0}"] = "إصدار جديد: {0}",
            ["نسخة ويندوز هذي ما تعطي الإشعارات للبرامج"] = "إصدار ويندوز هذا لا يتيح الإشعارات للبرامج",
            ["نفس اللون للحدود"] = "اللون نفسه للحدود",
