            ["نفس لون التاسك بار"] = "لون شريط المهام نفسه",
            ["نفس لون كتابة التاسك بار"] = "لون كتابة شريط المهام نفسه",
            ["نوافذ صغيرة تحطها على سطح المكتب، تتحاذى مع الأيقونات وتقدر تكبّرها وتصغّرها."] = "نوافذ صغيرة تضعها على سطح المكتب، تصطف مع الأيقونات ويمكنك تكبيرها وتصغيرها.",
            ["نوافذ صغيرة على سطح المكتب تتحاذى مع الأيقونات، أولها أصوات البرامج"] = "نوافذ صغيرة على سطح المكتب تصطف مع الأيقونات، أولها أصوات البرامج",
            ["هالأزرار مستخدمة في اختصار ثاني"] = "هذه المفاتيح مستخدمة في اختصار آخر",
            ["هذا الرابط من سبوتيفاي مو أغنية وحدة. انسخ رابط أغنية (مو ألبوم أو قائمة)."] = "هذا الرابط من سبوتيفاي ليس أغنية واحدة. انسخ رابط أغنية (لا ألبوم ولا قائمة).",
            ["هذا اللي في الكمبيوتر"] = "هذا ما في الحاسوب",
            ["هذا الملف مو ملف إعدادات Wibn"] = "هذا الملف ليس ملف إعدادات Wibn",
            ["هذا الموقع ما ينفع منه التحميل، أو الرابط مو رابط مقطع أو صورة."] = "لا يمكن التنزيل من هذا الموقع، أو الرابط ليس رابط مقطع أو صورة.",
            ["هذا جزء أساسي من ويندوز.\nلو قفلته الجهاز بيطيح (شاشة زرقا أو يطلعك من حسابك) وكل شي مفتوح وما انحفظ بيروح."] = "هذا جزء أساسي من ويندوز.\nإذا أنهيته سيسقط الجهاز (شاشة زرقاء أو تسجيل خروج من حسابك) وسيضيع كل ما هو مفتوح ولم يُحفظ.",
            ["هذا جزء من ويندوز أو خدمة تشتغل بالخلفية.\nقفله ممكن يخرّب شي في الجهاز (مثل التاسك بار أو الصوت أو النت أو الحماية) لين تعيد التشغيل."] = "هذا جزء من ويندوز أو خدمة تعمل في الخلفية.\nقد يُفسد إنهاؤه شيئًا في الجهاز (مثل شريط المهام أو الصوت أو الإنترنت أو الحماية) حتى تعيد التشغيل.",
            ["هذا مجلد مهم للنظام وما ينقفل."] = "هذا مجلد مهم للنظام ولا يمكن قفله.",
            ["هذا مجلد نظام وما يترتب."] = "هذا مجلد نظام ولا يُرتَّب.",
            ["هذا مو كود صحيح. انسخه كامل من خويك."] = "هذا ليس رمزًا صحيحًا. انسخه كاملًا من صديقك.",
            ["هذا مو ملف cookies.txt. صدّره بصيغة Netscape (الإضافة تسويها كذا)."] = "هذا ليس ملف cookies.txt. صدّره بصيغة Netscape (وهي ما تفعله الإضافة).",
            ["وأنت تسحب أي ملف من المستكشف أو سطح المكتب، اضغط Space وتطلع قائمة دائرية بالصيغ. حط الملف على الصيغة وخلاص."] = "أثناء سحب أي ملف من المستكشف أو سطح المكتب، اضغط Space لتظهر قائمة دائرية بالصيغ. ضع الملف على الصيغة وانتهى الأمر.",
            ["وأنت تسحب أي ملف من المستكشف أو سطح المكتب، اضغط Space وتطلع قائمة دائرية تحت الماوس. أفلت الملف على الصيغة اللي تبيها والملف نفسه يتحول. Space مرة ثانية أو Esc يسكّرها."] = "أثناء سحب أي ملف من المستكشف أو سطح المكتب، اضغط Space لتظهر قائمة دائرية تحت المؤشر. أفلت الملف على الصيغة التي تريدها ليتحول الملف نفسه. اضغط Space مرة أخرى أو Esc لإغلاقها.",
            ["وأنت تسحب الملف اضغط C، ويطلع لك ملف أصغر بنفس الشكل تقريبًا. وما يطلع أكبر من الأصل أبد."] = "أثناء سحب الملف اضغط C، فيظهر لك ملف أصغر بالشكل نفسه تقريبًا، ولا يكون أكبر من الأصل أبدًا.",
            ["وأنت تسحب صورة أو مقطع اضغط R، وتختار الحجم اللي تبيه."] = "أثناء سحب صورة أو مقطع اضغط R، واختر الحجم الذي تريده.",
            ["وأنت تسحب من المستكشف أو سطح المكتب، اضغط C وتطلع قائمة دائرية تحت الماوس. أفلت الملف على المستوى اللي تبيه والملف نفسه يصغر. C مرة ثانية أو Esc يسكّرها. لو النتيجة مو أصغر يبقى الملف مثل ما هو، والأصل ينحفظ 30 يوم."] = "أثناء السحب من المستكشف أو سطح المكتب، اضغط C لتظهر قائمة دائرية تحت المؤشر. أفلت الملف على المستوى الذي تريده ليصغر الملف نفسه. اضغط C مرة أخرى أو Esc لإغلاقها. إذا لم تكن النتيجة أصغر يبقى الملف كما هو، ويُحفظ الأصل 30 يومًا.",
            ["وأنت تسحب من المستكشف أو سطح المكتب، اضغط R وتطلع قائمة دائرية تحت الماوس. أفلت الملف على المقاس اللي تبيه والملف نفسه يتغير. R مرة ثانية أو Esc يسكّرها. الأصل ينحفظ 30 يوم عشان ترجع له."] = "أثناء السحب من المستكشف أو سطح المكتب، اضغط R لتظهر قائمة دائرية تحت المؤشر. أفلت الملف على المقاس الذي تريده ليتغير الملف نفسه. اضغط R مرة أخرى أو Esc لإغلاقها. يُحفظ الأصل 30 يومًا لتعود إليه.",
            ["وأنت تسحب من المستكشف أو سطح المكتب، اضغط Z وتطلع قائمة دائرية تحت الماوس. أفلت الملفات على الصيغة اللي تبيها ويطلع ملف مضغوط واحد جنبها، والأصل يبقى مثل ما هو. Z مرة ثانية أو Esc يسكّرها."] = "أثناء السحب من المستكشف أو سطح المكتب، اضغط Z لتظهر قائمة دائرية تحت المؤشر. أفلت الملفات على الصيغة التي تريدها ليظهر ملف مضغوط واحد بجانبها، ويبقى الأصل كما هو. اضغط Z مرة أخرى أو Esc لإغلاقها.",
            ["وأنت تلعب، الماوس تحت ما يطلّع التاسك بار. يطلع بس لما تضغط زر الويندوز"] = "أثناء اللعب لا يُظهر المؤشر في الأسفل شريطَ المهام. يظهر فقط عند ضغط زر ويندوز",
            ["وأي موقع ثاني تدعمه yt-dlp (أكثر من ألف موقع)"] = "وأي موقع آخر يدعمه yt-dlp (أكثر من ألف موقع)",
            ["وبعد كل تصوير يطلع لك إشعار صغير في الزاوية، اضغط عليه عشان تفتح الملف."] = "وبعد كل تصوير يظهر إشعار صغير في الزاوية، اضغط عليه لفتح الملف.",
            ["ودّ الماوس لطرف الشاشة اليسار فوق التاسك بار، ويطلع لسان (بس إذا ما فيه برنامج مغطي هالمكان). اضغطه وتطلع قائمة بكل ملفات سطح المكتب. كليك يمين على أي ملف: قص، نسخ، تغيير الاسم، حذف، والخصائص."] = "حرّك المؤشر إلى الطرف الأيسر من الشاشة فوق شريط المهام، فيظهر لسان (إذا لم يكن هناك برنامج يغطي هذا المكان). اضغطه لتظهر قائمة بجميع ملفات سطح المكتب. انقر بالزر الأيمن على أي ملف: قص، ونسخ، وإعادة التسمية، وحذف، والخصائص.",
            ["ودّ الماوس للزاوية اللي يسار تحت ويطلع لك مربع صغير، اضغطه وتطلع قائمة فيها كل اللي على سطح المكتب"] = "حرّك المؤشر إلى الزاوية اليسرى السفلية ليظهر مربع صغير، اضغطه لتظهر قائمة بكل ما على سطح المكتب",
            ["وش البرامج اللي ماخذة أكثر رام الحين."] = "البرامج التي تستهلك أكبر قدر من الذاكرة الآن.",
