            ["يحتاج Wibn يعيد التشغيل عشان يصير بالعربي. أعيد التشغيل الحين؟"] = "يحتاج Wibn إلى إعادة التشغيل ليصبح بالعربية. هل أعيد التشغيل الآن؟",
            ["يحتاج تجهيز مرة وحدة"] = "يحتاج إلى تجهيز مرة واحدة",
            ["يحذف الملفات المؤقتة وكاش البرامج والمتصفحات. ويندوز والبرامج يرجعون يسوونها لما يحتاجونها، فحذفها آمن."] = "يحذف الملفات المؤقتة وذاكرة التخزين المؤقت للبرامج والمتصفحات. تعيد ويندوز والبرامج إنشاءها عند الحاجة، فحذفها آمن.",
            ["يحس كأنه {0} · رطوبة {1}% · رياح {2} كم/س"] = "الإحساس كأنها {0} · رطوبة {1}% · رياح {2} كم/س",
            ["يحفظ اللي صار على الشاشة قبل لا تضغط. يحتاج التسجيل المستمر يكون شغّال (تحت)"] = "يحفظ ما حدث على الشاشة قبل أن تضغط. يتطلب تشغيل التسجيل المستمر (في الأسفل)",
            ["يحمّل البرامج في الرام مسبقًا، ويشغّل القرص كثير أثناء اللعب"] = "يحمّل البرامج في الذاكرة مسبقًا، ويُكثر من استخدام القرص أثناء اللعب",
            ["يحمّل ويثبّت التحديثات في الخلفية، ويسحب من المعالج والنت والقرص"] = "ينزّل التحديثات ويثبّتها في الخلفية، ويستهلك من المعالج والإنترنت والقرص",
            ["يختفي قدام البرامج المكبّرة أو بملء الشاشة، ويطلع لما تقرّب الماوس من جهته"] = "يختفي أمام البرامج المكبّرة أو بملء الشاشة، ويظهر عند تقريب المؤشر من جهته",
            ["يختفي لما تكون نافذة تحته"] = "يختفي عندما تكون نافذة تحته",
            ["يختفي مع ملء الشاشة والتكبير"] = "يختفي في وضع ملء الشاشة والتكبير",
            ["يخفي تاسك بار ويندوز ويحط بداله تاسك بار تقدر تغيّر شكله كله. ويندوز نفسه ما يتغيّر فيه شي، وتاسك باره يرجع لما تطفيه أو يتسكّر Wibn"] = "يخفي شريط مهام ويندوز ويضع مكانه شريط مهام يمكنك تغيير شكله بالكامل. لا يتغير شيء في ويندوز نفسه، ويعود شريط مهامه عند إيقافه أو إغلاق Wibn",
            ["يخفي تاسك بار ويندوز ويحط بداله تاسك بار من Wibn: ستارت والبحث، برامجك المثبتة والمفتوحة (كليك يفتحها أو يصغّرها، وقف عليها بالماوس وتشوف صورة حية لنوافذها واضغط على الصورة عشان تروح لهالنافذة بالذات. ولو البرنامج فيه أكثر من نافذة، كليك عليه يطلّع كل نوافذه وكليك ثاني يخفيها كلها. وحرّك عجلة الماوس على أيقونة برنامج عشان ترفع أو توطّي صوته هو بس)، ولغة الكيبورد (كليك عليها يغيّرها)، والنت والصوت (حرّك عجلة الماوس عليه عشان ترفع أو تنزّل الصوت) والساعة. تختار شكله: كامل أو عائم (الويدجتات اللي على الأطراف تتحاذى معه، وبينه وبين الويدجتات نفس المسافة اللي بين الويدجتات) أو دوك بالنص، وسماكته، وينزل ويختفي لما تكبّر نافذة أو يكون برنامج أو لعبة بملء الشاشة (النافذة المكبّرة تاخذ الشاشة كلها) (ودّ الماوس لآخر الشاشة تحت ويطلع، وشيل الماوس عنه وينزل، ولما تضغط زر ويندوز وتنفتح قائمة ابدأ أو البحث يطلع معها، وتقدر تطفي هالشي)، والخلفية زجاج (بإعدادات صفحة Liquid Glass، يوريك اللي وراه على طول مثل الفيديو والنوافذ، وتطلع في السكرين شوت (PrintScreen وWin+Shift+S وتصوير Wibn)، وفي البث والتسجيل مثل ديسكورد وOBS تطلع مع خيار \"يظهر في البث\"، ويصير لحاله مع OBS) أو لون أو شفاف، وحجم الأيقونات ومكانها. اسحب أي برنامج عليه عشان تثبّته، واسحب المثبتة عشان ترتبها. ولو تبيه أقصر، اسحبه من طرفه اليمين أو اليسار لجوّا (الطرفين يتحركون مع بعض ويبقى بالنص)، ودبل كليك على الطرف يرجّعه بطوله الكامل. تصغيره ما يحرّك الويدجتات. وتقدر تنقله لأي طرف: امسكه من مكان فاضي فيه واسحبه لفوق أو يمين أو يسار أو تحت، يطلع لك مكانه الجديد ملوّن، وأول ما تفلته ينتقل (يمين أو يسار يصير عمودي). النوافذ المكبّرة والويدجتات يفسحون له مكان ويتوزعون من جديد، وEsc يلغي السحب. ولو تبي الساعة واللي حولها في تاسك بار لحالها، شغّل \"الساعة في تاسك بار منفصل\" من صفحة التاسك بار: البرامج تصير في قطعة والساعة في قطعة ثانية، وكل وحدة لها زجاجها. ولو تبي الساعة فوق والبرامج تحت (أو العكس)، امسك قطعة الساعة من مكان فاضي واسحبها لفوق (تروح لنفس الجهة اللي كانت فيها آخر مرة، يمين أو يسار، وتغيّرها من كليك يمين عليها ← جهة تاسك بار الساعة)، واسحبها لنفس طرف البرامج عشان ترجع جنبها. النوافذ والويدجتات يفسحون لها مكان. وتقدر تطوّل أي قطعة: اسحب طرف قطعة البرامج (الطرفين لو هي بالنص) أو طرف قطعة الساعة الداخلي (اللي جهة النص) لبرّا عشان تطول، ولجوّا عشان تقصر، ودبل كليك على الطرف يرجّعها على قد اللي فيها. ولو الساعة في تاسك بار لحالها، اضغط Shift وإنت تسحب طرفها، ويتوازن مع أقرب ويدجت فوقه (أو تحته) ويصيرون بنفس العرض. وكليك يمين على مكان فاضي في التاسك بار يطلّع القائمة عند الماوس. ولو طوّلت قطعة الساعة، كليك يمين عليها ← مكان الساعة في التاسك بار عشان تختار يمين أو يسار أو الوسط. وأيقونات البرامج اللي جنب الساعة (ديسكورد، ستيم…) تطلع فيه نفسه: تختار من صفحة التاسك بار أيها يبان، والباقي تحت السهم. كليك وكليك يمين عليها مثل ويندوز بالضبط."] = "يخفي شريط مهام ويندوز ويضع مكانه شريط مهام من Wibn: زر ابدأ والبحث، وبرامجك المثبتة والمفتوحة (النقر يفتحها أو يصغّرها، وعند الوقوف عليها بالمؤشر ترى صورة حية لنوافذها، واضغط على الصورة للانتقال إلى تلك النافذة تحديدًا. وإذا كان للبرنامج أكثر من نافذة، فالنقر عليه يُظهر جميع نوافذه والنقر مرة أخرى يخفيها كلها. وحرّك عجلة الفأرة فوق أيقونة برنامج لرفع صوته هو فقط أو خفضه)، ولغة لوحة المفاتيح (النقر عليها يغيّرها)، والإنترنت والصوت (حرّك عجلة الفأرة عليه لرفع الصوت أو خفضه) والساعة. تختار شكله: كامل أو عائم (تصطف الودجات على الأطراف معه، وتكون المسافة بينه وبين الودجات مثل المسافة بين الودجات نفسها) أو شريط في المنتصف، وسُمكه، وينسحب ويختفي عند تكبير نافذة أو تشغيل برنامج أو لعبة بملء الشاشة (فتأخذ النافذة المكبّرة الشاشة كلها) (حرّك المؤشر إلى أسفل الشاشة ليظهر، وأبعد المؤشر عنه لينسحب، وعند الضغط على زر ويندوز وفتح قائمة ابدأ أو البحث يظهر معها، ويمكنك إيقاف ذلك)، والخلفية زجاج (بإعدادات صفحة Liquid Glass، يعرض ما خلفه لحظة بلحظة مثل الفيديو والنوافذ، ويظهر في لقطات الشاشة (PrintScreen وWin+Shift+S وتصوير Wibn)، وفي البث والتسجيل مثل ديسكورد وOBS يظهر مع خيار «يظهر في البث»، ويحدث ذلك تلقائيًا مع OBS) أو لون أو شفاف، وحجم الأيقونات ومكانها. اسحب أي برنامج إليه لتثبيته، واسحب المثبتة لترتيبها. وإذا أردته أقصر، فاسحبه من طرفه الأيمن أو الأيسر إلى الداخل (يتحرك الطرفان معًا ويبقى في المنتصف)، والنقر المزدوج على الطرف يعيده بطوله الكامل. تقصيره لا يحرّك الودجات. ويمكنك نقله إلى أي حافة: أمسكه من مكان فارغ فيه واسحبه إلى الأعلى أو اليمين أو اليسار أو الأسفل، فيظهر مكانه الجديد ملوّنًا، وبمجرد إفلاته ينتقل (على اليمين أو اليسار يصبح عموديًا). وتفسح له النوافذ المكبّرة والودجات مكانًا وتتوزع من جديد، وEsc يلغي السحب. وإذا أردت الساعة وما حولها في شريط مستقل، فشغّل «الساعة في شريط مهام منفصل» من صفحة شريط المهام: تصبح البرامج في قطعة والساعة في قطعة أخرى، ولكل منهما زجاجها. وإذا أردت الساعة في الأعلى والبرامج في الأسفل (أو العكس)، فأمسك قطعة الساعة من مكان فارغ واسحبها إلى الأعلى (تذهب إلى الجهة التي كانت فيها آخر مرة، يمينًا أو يسارًا، ويمكنك تغييرها بالنقر عليها بالزر الأيمن ← جهة شريط الساعة)، واسحبها إلى حافة البرامج نفسها لتعود بجانبها. وتفسح لها النوافذ والودجات مكانًا. ويمكنك إطالة أي قطعة: اسحب طرف قطعة البرامج (الطرفين إن كانت في المنتصف) أو الطرف الداخلي لقطعة الساعة (الذي جهة المنتصف) إلى الخارج لتطول، وإلى الداخل لتقصر، والنقر المزدوج على الطرف يعيدها بقدر ما فيها. وإذا كانت الساعة في شريط مستقل، فاضغط Shift أثناء سحب طرفها لتتساوى مع أقرب ودجة فوقها (أو تحتها) فيصبحان بالعرض نفسه. والنقر بالزر الأيمن على مكان فارغ في شريط المهام يُظهر القائمة عند المؤشر. وإذا أطلت قطعة الساعة، فانقر عليها بالزر الأيمن ← مكان الساعة في شريط المهام لتختار اليمين أو اليسار أو الوسط. وتظهر أيقونات البرامج المجاورة للساعة (ديسكورد، ستيم…) فيه أيضًا: تختار من صفحة شريط المهام أيها يظهر، والباقي تحت السهم. والنقر والنقر بالزر الأيمن عليها مثل ويندوز تمامًا.",
